package odc;
import java.util.*;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.inventory.*;
import net.minecraft.item.ItemStack;
import net.minecraft.util.math.BlockPos;
import net.minecraft.world.World;
import net.minecraft.tileentity.TileEntity;

/** Read-only device panels and DataOS. All actions are validated server-side. */
final class PanelMenu extends Container {
    final EntityPlayer player;final Tiles.Owned tile;final int type,bay,revision;final ItemStack opened;
    final int[] data=new int[420],previous=new int[840];int tab,page,selected,creation,port,group,coin;boolean personal;long lastRefresh=Long.MIN_VALUE;
    final List<UUID> visibleServers=new ArrayList<>();final List<Integer> visibleJobs=new ArrayList<>();
    PanelMenu(int id,EntityPlayer p,Tiles.Owned t){player=p;tile=t;type=id==2?0:id<40?1:2;bay=type==0?-1:id%20;revision=t instanceof Tiles.Rack?((Tiles.Rack)t).revision:0;opened=type==0?ItemStack.EMPTY:((Tiles.Rack)t).slots.get(bay);Arrays.fill(previous,-1);}
    @Override public boolean canInteractWith(EntityPlayer p){BlockPos b=tile.getPos();if(tile.getWorld()!=p.world||p.world.getTileEntity(b)!=tile||!tile.allows(p)||p.getDistanceSq(b.getX()+.5,b.getY()+.5,b.getZ()+.5)>64)return false;if(type==0)return true;Tiles.Rack r=(Tiles.Rack)tile;return r.role!=-1&&r.revision==revision&&bay<r.capacity()&&(p.world.isRemote||r.slots.get(bay)==opened);}
    @Override public ItemStack transferStackInSlot(EntityPlayer p,int i){return ItemStack.EMPTY;}
    List<Menus.Target> servers(){List<Menus.Target> list=new ArrayList<>();Network.Domain net=Network.scan(player.world,tile.getPos());if(net!=null)for(Tiles.Owned t:net.devices)if(t instanceof Tiles.Rack&&Objects.equals(tile.owner,t.owner)){Tiles.Rack r=(Tiles.Rack)t;for(int i=0;i<r.capacity();i++)if(r.isServer(i))list.add(new Menus.Target(r,i));}return list;}
    List<TaskData.Job> jobs(TaskData d){Set<UUID> ids=new HashSet<>();Network.Domain n=Network.scan(player.world,tile.getPos());if(n!=null)for(Tiles.Owned t:n.devices)if(t instanceof Tiles.Computer&&Objects.equals(tile.owner,t.owner))ids.add(((Tiles.Computer)t).id);List<TaskData.Job> list=new ArrayList<>();for(TaskData.Job j:d.jobs)if(Objects.equals(tile.owner,j.owner)&&ids.contains(j.anchor))list.add(j);return list;}
    TaskData.Job job(List<TaskData.Job> jobs){for(TaskData.Job j:jobs)if(j.id==selected)return j;return null;}
    static void putText(int[] a,int offset,int len,String text){for(int i=0;i<len&&i*2<text.length();i++)a[offset+i]=text.charAt(i*2)|(i*2+1<text.length()?text.charAt(i*2+1)<<16:0);}
    static String getText(int[] a,int offset,int len){StringBuilder s=new StringBuilder();for(int i=0;i<len;i++){int x=a[offset+i];char lo=(char)(x&65535),hi=(char)(x>>>16);if(lo==0)break;s.append(lo);if(hi==0)break;s.append(hi);}return s.toString();}
    static int nextCap(int current,int[] values){for(int i=0;i<values.length;i++)if(values[i]==current)return values[(i+1)%values.length];return values[0];}
    static int cap(long x){return (int)Math.max(0,Math.min(Integer.MAX_VALUE,x));}
    static void putLong(int[] a,int i,long x){a[i]=(int)x;a[i+1]=(int)(x>>>32);}
    static long getLong(int[] a,int i){return (a[i]&0xffffffffL)|((long)a[i+1]<<32);}
    boolean rename(EntityPlayer p,int expected,String name){if(!canInteractWith(p)||name==null)return false;name=name.trim();if(name.isEmpty()||name.length()>32||name.chars().anyMatch(c->c<32||c==167||c==127))return false;if(type==1&&expected==bay){Tiles.Rack r=(Tiles.Rack)tile;r.slots.get(bay).setStackDisplayName(name);r.changed();lastRefresh=Long.MIN_VALUE;return true;}if(type==0&&((Tiles.Computer)tile).online&&selected==expected){TaskData d=TaskData.get(p.world);TaskData.Job j=job(jobs(d));if(j==null)return false;j.name=name;d.markDirty();lastRefresh=Long.MIN_VALUE;return true;}return false;}
    @Override public boolean enchantItem(EntityPlayer p,int action){if(p.world.isRemote||!canInteractWith(p))return false;lastRefresh=Long.MIN_VALUE;
        if(type==1)return action==1&&((Tiles.Rack)tile).toggle(bay);
        if(type==2){Tiles.Rack r=(Tiles.Rack)tile;if(action>=10&&action<18){int n=action-10;if(n>=Hardware.ports(r.switchTier()))return false;port=n;return true;}if(action>=20&&action<29){int b=action-20;if(r.portOf(b)>=0)return false;return r.connect(b,port,p);}if(action==30&&r.ports[port]>0)return r.connect(r.ports[port]-1,port,p);return false;}
        Tiles.Computer c=(Tiles.Computer)tile;TaskData d=TaskData.get(p.world);if(action>=1&&action<=9){tab=action-1;page=0;return true;}if(action==90){page=Math.max(0,page-1);return true;}if(action==91){page++;return true;}if(!c.online)return false;List<TaskData.Job> jobs=jobs(d);TaskData.Job j=job(jobs);UUID corp=ClusterScheduler.key(c);
        if(tab==2){if(action==11){creation=(creation+1)%6;return true;}if(action==12){if(d.next==Integer.MAX_VALUE)return false;TaskData.Job newJob=new TaskData.Job(d.next++,creation,corp,c.owner==null?p.getUniqueID():c.owner);d.jobs.add(newJob);selected=newJob.id;page=Math.max(0,(jobs.size())/4);d.event(tile.owner,"Created task #"+selected);return true;}if(action>=20&&action<24){int row=action-20;if(row>=visibleJobs.size())return false;selected=visibleJobs.get(row);return true;}}
        if((tab==2||tab==3)&&j!=null){switch(action){case 30:if(j.type==TaskEngine.AI&&j.progress>=100000)return false;j.enabled=!j.enabled;d.event(j.owner,(j.enabled?"Started #":"Stopped #")+j.id);break;case 31:j.auto=!j.auto;break;case 32:j.strict=!j.strict;break;case 33:j.priority=j.priority%10+1;break;case 34:if(j.type==TaskEngine.AI||j.type==TaskEngine.INFERENCE)return false;j.cpu=Math.max(0,j.cpu-25);break;case 35:if(j.type==TaskEngine.AI||j.type==TaskEngine.INFERENCE)return false;j.cpu=Math.min(100000,j.cpu+25);break;case 36:if(j.type==TaskEngine.BANK)return false;j.gpus=Math.max(0,j.gpus-1);break;case 37:if(j.type==TaskEngine.BANK)return false;j.gpus=Math.min(4000,j.gpus+1);break;case 38:j.ram=Math.max(2,j.ram-2);break;case 39:j.ram=Math.min(100000,j.ram+2);break;case 40:j.net=Math.max(1,j.net-4);break;case 41:j.net=Math.min(1000000,j.net+4);break;case 42:j.group=(j.group+1)%10;break;case 44:j.disk=Math.max(1,j.disk-4);break;case 45:j.disk=Math.min(1000000,j.disk+4);break;case 43:d.jobs.remove(j);selected=0;d.event(tile.owner,"Deleted task #"+j.id);return true;default:return false;}d.markDirty();return true;}
        if(tab==1){List<Menus.Target> targets=servers();if(action==11){group=(group+1)%10;return true;}if(action==12||action==13||action==14){for(Menus.Target t:targets){UUID id=ClusterScheduler.serverId(t.item);if(group>0&&d.groups.getOrDefault(id,0)!=group)continue;if(action==14&&j!=null){j.auto=false;j.manual.put(id,new TaskEngine.Limit());}else if(action!=14&&((t.rack.enabledMask&(1<<t.bay))!=0)!=(action==12))t.rack.toggle(t.bay);}d.markDirty();return true;}
            if(action>=50&&action<90){int row=(action-50)/10,op=(action-50)%10;if(row>=visibleServers.size())return false;UUID id=visibleServers.get(row);Menus.Target target=null;for(Menus.Target t:targets)if(ClusterScheduler.serverId(t.item).equals(id)){target=t;break;}if(target==null)return false;switch(op){case 0: return target.rack.toggle(target.bay);case 1:d.groups.put(id,(d.groups.getOrDefault(id,0)+1)%10);break;case 2:if(j==null)return false;j.auto=false;if(j.manual.containsKey(id))j.manual.remove(id);else j.manual.put(id,new TaskEngine.Limit());break;case 3:if(j==null||!j.manual.containsKey(id))return false;TaskEngine.Limit l=j.manual.get(id);l.cpu=(l.cpu+25)%125;break;case 4:case 5:case 6:case 7:if(j==null||!j.manual.containsKey(id))return false;j.manual.get(id).mask^=1<<(op-4);break;case 8:if(j==null||!j.manual.containsKey(id))return false;TaskEngine.Limit m=j.manual.get(id);m.ram=nextCap(m.ram,new int[]{Integer.MAX_VALUE,2,4,8,16,32,64,128,256});break;case 9:if(j==null||!j.manual.containsKey(id))return false;TaskEngine.Limit n=j.manual.get(id);n.net=nextCap(n.net,new int[]{Integer.MAX_VALUE,4,8,16,32,64,100,200,500,1000});break;default:return false;}d.markDirty();return true;}}
        if(tab==6){UUID wallet=personal?p.getUniqueID():corp;if(action==11){personal=!personal;return true;}if(action==12){coin=(coin+1)%3;return true;}if(action==13||action==14){boolean ok=d.transfer(action==13?corp:p.getUniqueID(),action==13?p.getUniqueID():corp,coin,1000);if(ok)d.event(tile.owner,"Transfer 1 "+TaskData.COINS[coin]);return ok;}if(action==15){boolean ok=d.exchange(wallet,coin,1000);if(ok)d.event(tile.owner,"Exchanged 1 "+TaskData.COINS[coin]);return ok;}if(action>=20&&action<24)return buy(p,d,wallet,action-20);}
        return false;
    }
    static boolean buy(EntityPlayer p,TaskData d,UUID wallet,int index){if(index<0||index>=ODC.market.length)return false;Market.Entry e=ODC.market[index];ItemStack s=e.stack();if(s.isEmpty()||d.wallet(wallet)[0]<e.priceMilli)return false;int room=0;for(ItemStack old:p.inventory.mainInventory){if(old.isEmpty())room+=s.getMaxStackSize();else if(ItemStack.areItemsEqual(old,s)&&ItemStack.areItemStackTagsEqual(old,s))room+=Math.max(0,old.getMaxStackSize()-old.getCount());if(room>=s.getCount())break;}if(room<s.getCount())return false;d.wallet(wallet)[0]-=e.priceMilli;d.markDirty();p.inventory.addItemStackToInventory(s);if(!s.isEmpty())p.dropItem(s,false);p.inventory.markDirty();d.event(p.getUniqueID(),"Purchased "+e.item);return true;}
    void refresh(){Arrays.fill(data,0);if(type!=0){Tiles.Rack r=(Tiles.Rack)tile;data[0]=r.capacity();data[1]=bay;data[2]=(r.enabledMask>>bay)&1;data[3]=(r.poweredMask>>bay)&1;data[4]=r.status[bay];data[5]=r.powerUsed[bay];data[6]=r.cpuUsed[bay];data[7]=r.gpuUsed[bay];data[8]=r.ramUsed[bay];data[9]=r.netUsed[bay];if(type==1){int[] p=Hardware.spec(r.slots.get(bay));System.arraycopy(p,0,data,20,p.length);data[10]=Hardware.units(r.slots.get(bay));putText(data,100,20,r.slots.get(bay).getDisplayName());}else{data[10]=r.switchTier();data[11]=port;data[12]=r.switchOnline?1:0;for(int i=0;i<8;i++)data[20+i]=r.ports[i];for(int i=0;i<r.capacity();i++){data[40+i]=Hardware.units(r.slots.get(i));data[50+i]=r.portOf(i)+1;}}return;}
        Tiles.Computer c=(Tiles.Computer)tile;TaskData d=TaskData.get(player.world);UUID corp=ClusterScheduler.key(c);List<TaskData.Job> jobs=jobs(d);TaskData.Job j=job(jobs);List<Menus.Target> targets=servers();data[0]=tab;data[1]=c.online?1:0;data[2]=c.racks;data[3]=c.servers;data[4]=c.uplink;data[5]=c.switching;data[6]=c.networkUsed;data[7]=c.clusterPower;data[8]=c.miningStats[2];data[9]=jobs.size();data[12]=creation;data[13]=selected;data[14]=group;data[15]=coin;data[16]=personal?1:0;for(int i=0;i<3;i++){putLong(data,20+i*2,d.wallet(corp)[i]);putLong(data,26+i*2,d.wallet(player.getUniqueID())[i]);data[32+i]=d.difficulty[i];data[35+i]=d.rate[i];}
        for(int i=0;i<4;i++)if(i<ODC.market.length){data[38+i]=ODC.market[i].priceMilli;if(tab==6){ItemStack item=ODC.market[i].stack();putText(data,180+i*24,24,item.isEmpty()?"Unavailable":item.getDisplayName()+" x"+item.getCount());}}
        if(tab==7){List<String> logs=d.eventsFor(tile.owner);for(int i=0;i<Math.min(6,logs.size());i++)putText(data,180+i*32,32,logs.get(logs.size()-1-i));}
        if(tab==8){for(TaskData.Job job:jobs)if(job.type<3){data[70+job.type]+=job.work;if(job.enabled)data[73+job.type]++;}}
        if(j!=null){data[50]=j.id;data[51]=j.type;data[52]=j.enabled?1:0;data[53]=j.auto?1:0;data[54]=j.strict?1:0;data[55]=j.priority;data[56]=j.cpu;data[57]=j.gpus;data[58]=j.ram;data[59]=j.net;data[60]=j.group;data[61]=j.work;data[62]=j.usedCPU;data[63]=j.usedGPU;data[64]=j.usedRAM;data[65]=j.usedNet;data[66]=cap(j.progress);data[67]=j.full?1:0;data[68]=j.disk;data[69]=j.usedDisk;if(tab==3)putText(data,300,20,j.name);}
        int n=tab==1?targets.size():tab==2?jobs.size():1;int per=tab==1?3:4;int pages=Math.max(1,(n+per-1)/per);page=Math.min(Math.max(0,page),pages-1);data[10]=page;data[11]=pages;visibleServers.clear();visibleJobs.clear();
        for(int row=0;row<per;row++){int idx=page*per+row,k=80+row*24;if(tab==1&&idx<targets.size()){Menus.Target t=targets.get(idx);UUID id=ClusterScheduler.serverId(t.item);visibleServers.add(id);int[] p=Hardware.spec(t.item);data[k]=1;data[k+1]=id.hashCode();data[k+2]=t.bay+1;data[k+3]=(t.rack.enabledMask>>t.bay)&1;data[k+4]=t.rack.status[t.bay];data[k+5]=t.rack.cpuUsed[t.bay];data[k+6]=t.rack.gpuUsed[t.bay];data[k+7]=t.rack.ramUsed[t.bay];data[k+8]=t.rack.netUsed[t.bay];data[k+9]=t.rack.powerUsed[t.bay];data[k+10]=d.groups.getOrDefault(id,0);data[k+11]=ServerSpec.ramGB(p);data[k+12]=Hardware.gpus(t.item);data[k+13]=ServerSpec.psu(p);data[k+14]=ServerSpec.nic(p);TaskEngine.Limit l=j==null?null:j.manual.get(id);data[k+15]=l==null?0:1;data[k+16]=l==null?0:l.cpu;data[k+17]=l==null?0:l.mask;data[k+18]=t.rack.getPos().getX();data[k+19]=t.rack.getPos().getY();data[k+20]=t.rack.getPos().getZ();data[k+21]=l==null?0:l.ram;data[k+22]=l==null?0:l.net;putText(data,180+row*24,24,t.item.getDisplayName());}
            else if(tab==2&&idx<jobs.size()){TaskData.Job a=jobs.get(idx);visibleJobs.add(a.id);data[k]=1;data[k+1]=a.id;data[k+2]=a.type;data[k+3]=a.enabled?1:0;data[k+4]=a.work;data[k+5]=cap(a.progress);putText(data,180+row*24,24,a.name);}}
    }
    @Override public void detectAndSendChanges(){super.detectAndSendChanges();if(player.world.isRemote)return;long now=player.world.getTotalWorldTime();if(lastRefresh!=Long.MIN_VALUE&&now-lastRefresh<5)return;lastRefresh=now;refresh();for(int i=0;i<data.length;i++){int lo=data[i]&65535,hi=data[i]>>>16;if(previous[i*2]!=lo){for(IContainerListener l:listeners)l.sendWindowProperty(this,i*2,lo);previous[i*2]=lo;}if(previous[i*2+1]!=hi){for(IContainerListener l:listeners)l.sendWindowProperty(this,i*2+1,hi);previous[i*2+1]=hi;}}}
    @Override public void updateProgressBar(int id,int v){if(id<0||id>=data.length*2)return;int i=id/2;data[i]=id%2==0?(data[i]&0xffff0000)|(v&65535):(data[i]&65535)|((v&65535)<<16);}
}
